def compute(vars):
    high = vars["v1"]
    low = vars["v2"]
    value = (high + low) / 2
    return {
        "value": value,
        "trace": {
            "high": high,
            "low": low,
            "count": 2,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "currency/share"
            }
        }
    }
